const menu=document.querySelector("#mobile-menu");menu.addEventListener("click",(event)=>{if(event.target===menu){menu.close();}});for(const link of menu.querySelectorAll("a[href]")){link.addEventListener("click",()=>{menu.close();});}const snsMenu=document.querySelector("#mobile-share-menu");snsMenu.addEventListener("click",(event)=>{if(event.target===snsMenu){snsMenu.close();}});document.querySelectorAll('[data-share="x"]').forEach(button=>{button.addEventListener('click',()=>{const url="https://twitter.com/intent/tweet?url="+encodeURIComponent(button.dataset.url)+"&text="+encodeURIComponent(button.dataset.title);window.open(url,"_blank","noopener,noreferrer");});});document.querySelectorAll('[data-share="facebook"]').forEach(button=>{button.addEventListener('click',()=>{const url="https://www.facebook.com/sharer/sharer.php?u="+encodeURIComponent(button.dataset.url);window.open(url,"_blank","noopener,noreferrer");});});document.querySelectorAll('[data-share="hatena"]').forEach(button=>{button.addEventListener('click',()=>{const url="https://b.hatena.ne.jp/entry/"+encodeURIComponent(button.dataset.url).replace(/^https?:\/\//,"s/");window.open(url,"_blank","noopener,noreferrer");});});document.querySelectorAll('[data-share="line"]').forEach(button=>{button.addEventListener('click',()=>{const url="https://social-plugins.line.me/lineit/share?url="+encodeURIComponent(button.dataset.url);window.open(url,"_blank","noopener,noreferrer");});});const toast=document.getElementById("copy_toast");let toastTimer;function showCopyToast(){clearTimeout(toastTimer);toast.classList.add("show");toastTimer=setTimeout(()=>{toast.classList.remove("show");},2000);}document.querySelector(".copy_btn").addEventListener("click",function(){const input=this.previousElementSibling;navigator.clipboard.writeText(input.value);showCopyToast();});var pagetop=$('#pagetop');var pagebottom=$('#pagebottom');var toTop=1000;var toBottom=1000;$(window).scroll(function(){if($(this).scrollTop()>1000){pagetop.fadeIn();}else{pagetop.fadeOut();}if($(this).scrollTop()>0&&$(this).scrollTop()<$(document).height()-1200){pagebottom.fadeIn();}else{pagebottom.fadeOut();}});pagetop.click(function(){$('body, html').animate({scrollTop:0},toTop);});pagebottom.click(function(){$('body, html').animate({scrollTop:$(document).height()},toBottom);});Array.from(document.getElementsByTagName("a")).filter((a)=>{const href=(a.getAttribute("href")||"").trim().toLowerCase();if(href===""||href.startsWith("#")||href.startsWith("javascript:")||href.startsWith("mailto:")||href.startsWith("tel:")){return false;}return a.host!==window.location.host;}).forEach((a)=>{a.setAttribute("rel","noopener noreferrer");a.setAttribute("target","_blank");});